import useFetch from './hooks/useFetch.js';
function Quotes () {

    const {data, isPending, error} = useFetch('https://type.fit/api/quotes');
    let quote = data[Math.floor(Math.random() * data.length)].text;

    return (
        <div className="width-fit bg-white-opacity-30">
            <p>{quote}</p>
        </div>
    )
}

export default Quotes
